-- Preserve seed INSERT/default expressions, not one oracle's clock.
INSERT INTO playlist (name, type)
    VALUES ('Liked Songs', 1);

UPDATE playlist
SET position = (
    SELECT COUNT(*)
    FROM playlist AS p2
    WHERE p2.created_at < playlist.created_at
       OR (p2.created_at = playlist.created_at AND p2.id <= playlist.id)
);
